Object.assign(SNIP,{});PRESET_NOTES["l56"]={"Ví dụ: Dijkstra với hàng đợi ưu tiên": "Ví dụ kinh điển: dist = 0 7 9 20 20 11. Đỉnh 6 lúc đầu có dist 14 (cạnh thẳng 1 – 6), rồi được nới thành 11 qua 3. Đỉnh 6 có hai phần tử trong hàng đợi; phần tử (14, 6) bị bỏ qua khi lấy ra. Cạnh đậm là cây đường đi ngắn nhất.", "Ví dụ: Bản O(n²) không dùng đống": "Mỗi vòng duyệt n đỉnh để tìm đỉnh gần nhất: O(n²). Đỉnh được tô là đỉnh đã chốt. Đường tới 2 qua 3 (1 + 2 = 3) ngắn hơn cạnh thẳng (4). Kết quả 0 3 1 8 11.", "Ví dụ: In đường đi ngắn nhất": "Từ 5 đi ngược theo cha: 5 ← 6 ← 3 ← 1. Đường 1 → 3 → 6 → 5 dài 9 + 2 + 9 = 20.", "Ví dụ: Đếm số đường đi ngắn nhất": "Ba đường cùng dài 2 tới đỉnh 4: 1-2-4, 1-3-4 và cạnh thẳng 1-4. Khi một đỉnh được chốt, soDuong của nó đã đủ vì mọi đỉnh gần hơn đã xử lý xong.", "Lỗi: cạnh có độ dài âm": "In 1 3, nhưng đường ngắn nhất tới 4 là 1 → 3 → 2 → 4 dài 3 − 2 + 1 = 2. Đỉnh 2 được chốt sớm với dist 2 và đã nới sang 4; sau đó cạnh âm 3 → 2 làm dist[2] giảm, nhưng 4 không được cập nhật lại."};EX_HINTS["l56"]=[["Hàng đợi ưu tiên lấy nhỏ nhất chứa cặp {dist, đỉnh} (dist đứng trước để so sánh theo dist).", "Lấy ra (d, u); nếu d > dist[u] thì bỏ qua (phần tử cũ). Ngược lại nới mọi cạnh u → v.", "Quãng đường tới 10^5 · 10^9: dùng long long. Có thể có nhiều đường nối cùng một cặp nút."], ["Chạy Dijkstra kèm mảng soDuong, soDuong[1] = 1.", "Nới cạnh u → v: đường mới ngắn hơn hẳn thì soDuong[v] = soDuong[u]; bằng đúng dist[v] thì soDuong[v] += soDuong[u].", "Đúng vì mọi trọng số dương: khi u được chốt, mọi đỉnh đứng trước u trên đường ngắn nhất đã xử lý xong nên soDuong[u] đã đủ."], ["Đi được cả bốn hướng nên quy hoạch động theo hàng (bài 49) không đúng: đường tốt nhất có thể đi lên, đi sang trái.", "Coi mỗi ô là một đỉnh, cạnh vào ô (x, y) dài a[x][y] ≥ 0: chạy Dijkstra. Cất ô thành số x · C + y trong hàng đợi.", "Khởi đầu d[0][0] = a[0][0]; đáp án d[R − 1][C − 1]."]];
/* ===================== BÀI 56 · Thuật toán Dijkstra ===================== */
/* Bài 56 · Thuật toán Dijkstra
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR56=[{label:"Ví dụ: Dijkstra với hàng đợi ưu tiên",input:"6 8\n1 2 7\n1 3 9\n1 6 14\n2 3 10\n2 4 15\n3 4 11\n3 6 2\n6 5 9\n",code:"#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<pair<int,int>>> adj(n + 1);   // adj[u]: các cặp {v, w}\n    for (int i = 0; i < m; i++) {\n        int u, v, w;\n        cin >> u >> v >> w;\n        adj[u].push_back({v, w});\n        adj[v].push_back({u, w});\n    }\n    const long long INF = 4e18;\n    vector<long long> dist(n + 1, INF);\n    vector<int> cha(n + 1, 0);\n    priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;   // {dist, đỉnh}\n    dist[1] = 0;\n    pq.push({0, 1});\n    while (!pq.empty()) {\n        long long d = pq.top().first;\n        int u = pq.top().second;\n        pq.pop();\n        if (d > dist[u]) continue;            // phần tử cũ: bỏ qua\n        for (auto e : adj[u]) {\n            int v = e.first, w = e.second;\n            if (dist[u] + w < dist[v]) {      // nới cạnh u - v\n                dist[v] = dist[u] + w;\n                cha[v] = u;\n                pq.push({dist[v], v});\n            }\n        }\n    }\n\n    for (int u = 1; u <= n; u++) cout << dist[u] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,n:"n",lab:"dist",par:"cha",cur:["u","v"]},{type:"cont",of:"pq"}],py:{code:"import heapq\n\nn, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]       # adj[u]: các cặp (v, w)\nfor _ in range(m):\n    u, v, w = map(int, input().split())\n    adj[u].append((v, w))\n    adj[v].append((u, w))\nINF = float(\"inf\")\ndist = [INF] * (n + 1)\ncha = [0] * (n + 1)\ndist[1] = 0\npq = [(0, 1)]                          # (dist, đỉnh)\nwhile pq:\n    d, u = heapq.heappop(pq)\n    if d > dist[u]:                    # phần tử cũ: bỏ qua\n        continue\n    for v, w in adj[u]:\n        if d + w < dist[v]:            # nới cạnh u - v\n            dist[v] = d + w\n            cha[v] = u\n            heapq.heappush(pq, (dist[v], v))\nprint(*dist[1:])",viz:[{type:"graph",adj:"adj",base:1,n:"n",lab:"dist",par:"cha",cur:["u","v"]},{type:"cont",of:"pq",as:"priority_queue"}]},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        var adj = new List<int[]>[n + 1];      // adj[u]: các cặp { v, w }\n        for (int u = 0; u <= n; u++) adj[u] = new List<int[]>();\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(new[] { e[1], e[2] });\n            adj[e[1]].Add(new[] { e[0], e[2] });\n        }\n        const long INF = long.MaxValue;\n        long[] dist = new long[n + 1];\n        int[] cha = new int[n + 1];\n        bool[] xong = new bool[n + 1];\n        Array.Fill(dist, INF);\n        var pq = new PriorityQueue<int, long>(); // phần tử: đỉnh; độ ưu tiên: dist\n        dist[1] = 0;\n        pq.Enqueue(1, 0);\n        while (pq.Count > 0)\n        {\n            int u = pq.Dequeue();\n            if (xong[u]) continue;             // phần tử cũ: u đã được chốt\n            xong[u] = true;\n            foreach (int[] e in adj[u])\n            {\n                int v = e[0], w = e[1];\n                if (dist[u] + w < dist[v])     // nới cạnh u - v\n                {\n                    dist[v] = dist[u] + w;\n                    cha[v] = u;\n                    pq.Enqueue(v, dist[v]);\n                }\n            }\n        }\n        for (int u = 1; u <= n; u++) Console.Write(dist[u] + \" \");\n        Console.WriteLine();\n    }\n}",note:"Ví dụ kinh điển: dist = 0 7 9 20 20 11. Đỉnh 6 lúc đầu có dist 14 (cạnh thẳng 1 – 6), rồi được nới thành 11 qua 3; phần tử cũ của 6 bị bỏ qua nhờ mảng xong (PriorityQueue của .NET không cho đọc lại độ ưu tiên khi Dequeue, nên đánh dấu đỉnh đã chốt là cách gọn nhất).",viz:[{type:"graph",adj:"adj",base:1,n:"n",lab:"dist",par:"cha",mark:"xong",cur:["u","v"]},{type:"cont",of:"pq"}]}},{label:"Ví dụ: Bản O(n²) không dùng đống",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 5;\n    const int INF = 1000000000;\n    int w[6][6] = {};                  // ma trận trọng số, 0: không có cạnh\n    w[1][2] = w[2][1] = 4; w[1][3] = w[3][1] = 1; w[3][2] = w[2][3] = 2;\n    w[2][4] = w[4][2] = 5; w[3][4] = w[4][3] = 8; w[4][5] = w[5][4] = 3;\n    int dist[6];\n    bool xong[6] = {};\n    for (int i = 1; i <= n; i++) dist[i] = INF;\n    dist[1] = 0;\n    for (int k = 0; k < n; k++) {\n        int u = -1;\n        for (int i = 1; i <= n; i++)                    // tìm đỉnh chưa chốt gần nhất\n            if (!xong[i] && (u == -1 || dist[i] < dist[u])) u = i;\n        if (dist[u] == INF) break;\n        xong[u] = true;\n        for (int v = 1; v <= n; v++)\n            if (w[u][v] && dist[u] + w[u][v] < dist[v]) dist[v] = dist[u] + w[u][v];\n    }\n    for (int i = 1; i <= n; i++) cout << dist[i] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",mat:"w",lab:"dist",mark:"xong",cur:["u","v"]}],py:{code:"n = 5\nINF = 10**9\nw = [[0] * 6 for _ in range(6)]        # ma trận trọng số, 0: không có cạnh\nfor a, b, c in [(1, 2, 4), (1, 3, 1), (3, 2, 2), (2, 4, 5), (3, 4, 8), (4, 5, 3)]:\n    w[a][b] = w[b][a] = c\ndist = [INF] * 6\nxong = [False] * 6\ndist[1] = 0\nfor _ in range(n):\n    u = -1\n    for i in range(1, n + 1):          # tìm đỉnh chưa chốt gần nhất\n        if not xong[i] and (u == -1 or dist[i] < dist[u]):\n            u = i\n    if dist[u] == INF:\n        break\n    xong[u] = True\n    for v in range(1, n + 1):\n        if w[u][v] and dist[u] + w[u][v] < dist[v]:\n            dist[v] = dist[u] + w[u][v]\nprint(*dist[1:])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 5;\n        const int INF = 1000000000;\n        int[][] w = new int[6][];              // ma trận trọng số, 0: không có cạnh\n        for (int i = 0; i < 6; i++) w[i] = new int[6];\n        w[1][2] = w[2][1] = 4; w[1][3] = w[3][1] = 1; w[3][2] = w[2][3] = 2;\n        w[2][4] = w[4][2] = 5; w[3][4] = w[4][3] = 8; w[4][5] = w[5][4] = 3;\n        int[] dist = new int[6];\n        bool[] xong = new bool[6];\n        for (int i = 1; i <= n; i++) dist[i] = INF;\n        dist[1] = 0;\n        for (int k = 0; k < n; k++)\n        {\n            int u = -1;\n            for (int i = 1; i <= n; i++)       // tìm đỉnh chưa chốt gần nhất\n                if (!xong[i] && (u == -1 || dist[i] < dist[u])) u = i;\n            if (dist[u] == INF) break;\n            xong[u] = true;\n            for (int v = 1; v <= n; v++)\n                if (w[u][v] != 0 && dist[u] + w[u][v] < dist[v]) dist[v] = dist[u] + w[u][v];\n        }\n        for (int i = 1; i <= n; i++) Console.Write(dist[i] + \" \");\n        Console.WriteLine();\n    }\n}"}},{label:"Ví dụ: In đường đi ngắn nhất",input:"6 8\n1 2 7\n1 3 9\n1 6 14\n2 3 10\n2 4 15\n3 4 11\n3 6 2\n6 5 9\n",code:"#include <iostream>\n#include <vector>\n#include <queue>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<pair<int,int>>> adj(n + 1);   // adj[u]: các cặp {v, w}\n    for (int i = 0; i < m; i++) {\n        int u, v, w;\n        cin >> u >> v >> w;\n        adj[u].push_back({v, w});\n        adj[v].push_back({u, w});\n    }\n    const long long INF = 4e18;\n    vector<long long> dist(n + 1, INF);\n    vector<int> cha(n + 1, 0);\n    priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;   // {dist, đỉnh}\n    dist[1] = 0;\n    pq.push({0, 1});\n    while (!pq.empty()) {\n        long long d = pq.top().first;\n        int u = pq.top().second;\n        pq.pop();\n        if (d > dist[u]) continue;            // phần tử cũ: bỏ qua\n        for (auto e : adj[u]) {\n            int v = e.first, w = e.second;\n            if (dist[u] + w < dist[v]) {      // nới cạnh u - v\n                dist[v] = dist[u] + w;\n                cha[v] = u;\n                pq.push({dist[v], v});\n            }\n        }\n    }\n\n    int t = 5;\n    vector<int> duong;\n    for (int x = t; x != 0; x = cha[x]) duong.push_back(x);   // cha[1] = 0\n    reverse(duong.begin(), duong.end());\n    cout << dist[t] << \":\";\n    for (int x : duong) cout << \" \" << x;\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,n:"n",lab:"dist",par:"cha",cur:["x"]}],py:{code:"import heapq\n\nn, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]       # adj[u]: các cặp (v, w)\nfor _ in range(m):\n    u, v, w = map(int, input().split())\n    adj[u].append((v, w))\n    adj[v].append((u, w))\nINF = float(\"inf\")\ndist = [INF] * (n + 1)\ncha = [0] * (n + 1)\ndist[1] = 0\npq = [(0, 1)]                          # (dist, đỉnh)\nwhile pq:\n    d, u = heapq.heappop(pq)\n    if d > dist[u]:                    # phần tử cũ: bỏ qua\n        continue\n    for v, w in adj[u]:\n        if d + w < dist[v]:            # nới cạnh u - v\n            dist[v] = d + w\n            cha[v] = u\n            heapq.heappush(pq, (dist[v], v))\nt = 5\nduong = []\nx = t\nwhile x != 0:                          # cha[1] = 0\n    duong.append(x)\n    x = cha[x]\nduong.reverse()\nprint(str(dist[t]) + \":\", *duong)"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        var adj = new List<int[]>[n + 1];      // adj[u]: các cặp { v, w }\n        for (int u = 0; u <= n; u++) adj[u] = new List<int[]>();\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(new[] { e[1], e[2] });\n            adj[e[1]].Add(new[] { e[0], e[2] });\n        }\n        const long INF = long.MaxValue;\n        long[] dist = new long[n + 1];\n        int[] cha = new int[n + 1];\n        bool[] xong = new bool[n + 1];\n        Array.Fill(dist, INF);\n        var pq = new PriorityQueue<int, long>(); // phần tử: đỉnh; độ ưu tiên: dist\n        dist[1] = 0;\n        pq.Enqueue(1, 0);\n        while (pq.Count > 0)\n        {\n            int u = pq.Dequeue();\n            if (xong[u]) continue;             // phần tử cũ: u đã được chốt\n            xong[u] = true;\n            foreach (int[] e in adj[u])\n            {\n                int v = e[0], w = e[1];\n                if (dist[u] + w < dist[v])     // nới cạnh u - v\n                {\n                    dist[v] = dist[u] + w;\n                    cha[v] = u;\n                    pq.Enqueue(v, dist[v]);\n                }\n            }\n        }\n        int t = 5;\n        var duong = new List<int>();\n        for (int x = t; x != 0; x = cha[x]) duong.Add(x);   // cha[1] = 0\n        duong.Reverse();\n        Console.WriteLine(dist[t] + \": \" + string.Join(\" \", duong));\n    }\n}",viz:[{type:"graph",adj:"adj",base:1,n:"n",lab:"dist",par:"cha"}]}},{label:"Ví dụ: Đếm số đường đi ngắn nhất",input:"4 5\n1 2 1\n1 3 1\n2 4 1\n3 4 1\n1 4 2\n",code:"#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<pair<int,int>>> adj(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v, w;\n        cin >> u >> v >> w;\n        adj[u].push_back({v, w});\n        adj[v].push_back({u, w});\n    }\n    const long long INF = 4e18;\n    vector<long long> dist(n + 1, INF), soDuong(n + 1, 0);\n    priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;\n    dist[1] = 0;\n    soDuong[1] = 1;\n    pq.push({0, 1});\n    while (!pq.empty()) {\n        long long d = pq.top().first;\n        int u = pq.top().second;\n        pq.pop();\n        if (d > dist[u]) continue;\n        for (auto e : adj[u]) {\n            int v = e.first, w = e.second;\n            if (dist[u] + w < dist[v]) {             // đường mới ngắn hơn hẳn\n                dist[v] = dist[u] + w;\n                soDuong[v] = soDuong[u];\n                pq.push({dist[v], v});\n            } else if (dist[u] + w == dist[v]) {     // thêm một cách cùng độ dài\n                soDuong[v] += soDuong[u];\n            }\n        }\n    }\n    cout << dist[n] << \" \" << soDuong[n] << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,n:"n",lab:"soDuong",cur:["u","v"]}],py:{code:"import heapq\n\nn, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]       # adj[u]: các cặp (v, w)\nfor _ in range(m):\n    u, v, w = map(int, input().split())\n    adj[u].append((v, w))\n    adj[v].append((u, w))\nINF = float(\"inf\")\ndist = [INF] * (n + 1)\nso_duong = [0] * (n + 1)\ndist[1] = 0\nso_duong[1] = 1\npq = [(0, 1)]\nwhile pq:\n    d, u = heapq.heappop(pq)\n    if d > dist[u]:\n        continue\n    for v, w in adj[u]:\n        if d + w < dist[v]:            # đường mới ngắn hơn hẳn\n            dist[v] = d + w\n            so_duong[v] = so_duong[u]\n            heapq.heappush(pq, (dist[v], v))\n        elif d + w == dist[v]:         # thêm một cách cùng độ dài\n            so_duong[v] += so_duong[u]\nprint(dist[n], so_duong[n])"},cs:{code:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        var adj = new List<int[]>[n + 1];      // adj[u]: các cặp { v, w }\n        for (int u = 0; u <= n; u++) adj[u] = new List<int[]>();\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(new[] { e[1], e[2] });\n            adj[e[1]].Add(new[] { e[0], e[2] });\n        }\n        const long INF = long.MaxValue;\n        long[] dist = new long[n + 1], soDuong = new long[n + 1];\n        bool[] xong = new bool[n + 1];\n        Array.Fill(dist, INF);\n        var pq = new PriorityQueue<int, long>();\n        dist[1] = 0;\n        soDuong[1] = 1;\n        pq.Enqueue(1, 0);\n        while (pq.Count > 0)\n        {\n            int u = pq.Dequeue();\n            if (xong[u]) continue;\n            xong[u] = true;\n            foreach (int[] e in adj[u])\n            {\n                int v = e[0];\n                long nd = dist[u] + e[1];\n                if (nd < dist[v]) { dist[v] = nd; soDuong[v] = soDuong[u]; pq.Enqueue(v, nd); }   // ngắn hơn hẳn\n                else if (nd == dist[v]) soDuong[v] += soDuong[u];                                 // thêm một cách\n            }\n        }\n        Console.WriteLine(dist[n] + \" \" + soDuong[n]);\n    }\n}"}},{label:"Lỗi: cạnh có độ dài âm",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 4;\n    int eu[4] = {1, 1, 3, 2};\n    int ev[4] = {2, 3, 2, 4};\n    int ew[4] = {2, 3, -2, 1};         // cạnh 3 -> 2 âm\n    const int INF = 1000000000;\n    int dist[5] = {0, 0, INF, INF, INF};\n    bool xong[5] = {};\n    for (int k = 0; k < n; k++) {\n        int u = -1;\n        for (int i = 1; i <= n; i++)\n            if (!xong[i] && (u == -1 || dist[i] < dist[u])) u = i;\n        xong[u] = true;                // chốt u: Dijkstra tin dist[u] sẽ không đổi nữa\n        for (int j = 0; j < 4; j++)\n            if (eu[j] == u && dist[u] + ew[j] < dist[ev[j]]) dist[ev[j]] = dist[u] + ew[j];\n    }\n    cout << dist[2] << \" \" << dist[4] << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",eu:"eu",ev:"ev",ew:"ew",dir:true,lab:"dist",mark:"xong",cur:["u"]}],py:{code:"n = 4\ncanh = [(1, 2, 2), (1, 3, 3), (3, 2, -2), (2, 4, 1)]   # cạnh 3 -> 2 âm\nINF = 10**9\ndist = [0, 0, INF, INF, INF]\nxong = [False] * 5\nfor _ in range(n):\n    u = -1\n    for i in range(1, n + 1):\n        if not xong[i] and (u == -1 or dist[i] < dist[u]):\n            u = i\n    xong[u] = True                     # chốt u: Dijkstra tin dist[u] sẽ không đổi nữa\n    for a, b, w in canh:\n        if a == u and dist[u] + w < dist[b]:\n            dist[b] = dist[u] + w\nprint(dist[2], dist[4])",viz:[{type:"vars",names:["u","dist"]}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 4;\n        int[] eu = { 1, 1, 3, 2 };\n        int[] ev = { 2, 3, 2, 4 };\n        int[] ew = { 2, 3, -2, 1 };            // cạnh 3 -> 2 âm\n        const int INF = 1000000000;\n        int[] dist = { 0, 0, INF, INF, INF };\n        bool[] xong = new bool[5];\n        for (int k = 0; k < n; k++)\n        {\n            int u = -1;\n            for (int i = 1; i <= n; i++)\n                if (!xong[i] && (u == -1 || dist[i] < dist[u])) u = i;\n            xong[u] = true;                    // chốt u: Dijkstra tin dist[u] sẽ không đổi nữa\n            for (int j = 0; j < 4; j++)\n                if (eu[j] == u && dist[u] + ew[j] < dist[ev[j]]) dist[ev[j]] = dist[u] + ew[j];\n        }\n        Console.WriteLine(dist[2] + \" \" + dist[4]);\n    }\n}"}}];
const sim56=makeSim2(document.getElementById("sim-l56"),{id:"s56",presets:PR56});
makeEx2(document.getElementById("ex-l56"),sim56,[{t:"Khoảng cách trên bản đồ",d:"Bản đồ có n nút giao và m con đường hai chiều, đường i nối uᵢ, vᵢ dài wᵢ. Đầu vào: n m (1 ≤ n ≤ 10^5, 1 ≤ m ≤ 2·10^5) rồi m dòng u v w (1 ≤ w ≤ 10^9). Đầu ra: một dòng n số, số thứ i là quãng đường ngắn nhất từ nút 1 tới nút i, hoặc -1 nếu không tới được.",tests:[{in:"6 8\n1 2 7\n1 3 9\n1 6 14\n2 3 10\n2 4 15\n3 4 11\n3 6 2\n6 5 9",out:"0 7 9 20 20 11"},{in:"3 1\n2 3 5",out:"0 -1 -1"},{in:"2 2\n1 2 1000000000\n1 2 3",out:"0 3"},{in:"4 3\n1 2 1000000000\n2 3 1000000000\n3 4 1000000000",out:"0 1000000000 2000000000 3000000000"},{in:"40 80\n36 1 61\n34 20 99\n35 27 91\n15 7 48\n40 5 44\n17 37 27\n2 37 27\n4 38 72\n9 25 88\n2 10 50\n16 12 13\n40 13 72\n14 29 24\n25 9 86\n5 14 68\n12 13 23\n9 36 64\n24 1 85\n3 38 48\n1 37 87\n1 34 71\n7 40 64\n25 24 61\n24 13 66\n30 36 64\n3 14 24\n22 30 19\n1 13 39\n10 38 33\n30 1 17\n2 39 38\n33 11 99\n33 6 7\n38 19 78\n26 16 92\n4 33 62\n35 20 79\n14 4 84\n27 9 22\n40 35 74\n10 34 82\n2 3 5\n32 17 14\n33 9 6\n17 10 99\n38 37 89\n8 26 93\n15 14 76\n8 21 18\n35 9 95\n36 8 30\n27 26 92\n7 13 100\n16 19 14\n39 6 25\n8 3 84\n28 35 37\n39 10 90\n37 35 49\n26 16 91\n4 33 58\n22 25 16\n23 25 74\n20 7 58\n9 28 80\n24 30 40\n13 35 79\n2 28 11\n28 2 37\n17 40 90\n15 3 53\n9 14 51\n21 35 15\n17 4 58\n37 15 46\n1 2 60\n11 28 93\n16 40 13\n11 23 56\n12 31 43",out:"0 60 65 172 132 123 139 91 125 110 164 62 39 89 118 75 114 -1 89 170 109 36 126 57 52 166 147 71 113 17 105 128 130 71 108 61 87 113 98 88"}],start:"#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<pair<int,int>>> adj(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v, w;\n        cin >> u >> v >> w;\n        adj[u].push_back({v, w});\n        adj[v].push_back({u, w});\n    }\n    const long long INF = 4e18;\n    vector<long long> dist(n + 1, INF);\n    // Dijkstra từ 1 bằng priority_queue lấy nhỏ nhất, phần tử {dist, đỉnh}\n    for (int u = 1; u <= n; u++) cout << (dist[u] == INF ? -1 : dist[u]) << \" \";\n    cout << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const r=[];for(let i=1;i<n;i++)r.push(i+" "+(i+1)+" "+(1+(i*7)%10));for(let i=1;i+3<=n;i+=3)r.push(i+" "+(i+3)+" "+(5+(i*13)%40));return n+" "+r.length+"\n"+r.join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>120*n*Math.log2(n)+300,why:"Mỗi bước duyệt cả n đỉnh để tìm đỉnh gần nhất tốn O(n²) — chỉ hợp với đồ thị dày."},py:{start:"import heapq\n\nn, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]       # adj[u]: các cặp (v, w)\nfor _ in range(m):\n    u, v, w = map(int, input().split())\n    adj[u].append((v, w))\n    adj[v].append((u, w))\nINF = float(\"inf\")\ndist = [INF] * (n + 1)\n# Dijkstra từ 1 bằng heapq, phần tử (dist, đỉnh)\nprint(*(d if d != INF else -1 for d in dist[1:]))",hints:["heapq chứa bộ (dist, đỉnh): so theo dist trước.","Lấy ra (d, u); nếu d > dist[u] thì bỏ qua (phần tử cũ). Ngược lại nới mọi cạnh u → v.","Có thể có nhiều đường nối cùng một cặp nút: không ảnh hưởng."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        var adj = new List<int[]>[n + 1];      // adj[u]: các cặp { v, w }\n        for (int u = 0; u <= n; u++) adj[u] = new List<int[]>();\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(new[] { e[1], e[2] });\n            adj[e[1]].Add(new[] { e[0], e[2] });\n        }\n        const long INF = long.MaxValue;\n        long[] dist = new long[n + 1];\n        Array.Fill(dist, INF);\n        // Dijkstra từ 1: PriorityQueue<int, long> (đỉnh, dist) và mảng xong để bỏ phần tử cũ\n        var sb = new StringBuilder();\n        for (int u = 1; u <= n; u++) sb.Append(dist[u] == INF ? -1 : dist[u]).Append(' ');\n        Console.WriteLine(sb.ToString());\n    }\n}",hints:["PriorityQueue<int, long>: phần tử là đỉnh, độ ưu tiên là dist (nhỏ ra trước).","Dequeue u; nếu u đã chốt (xong[u]) thì bỏ qua — đó là phần tử cũ. Ngược lại chốt u và nới mọi cạnh u → v.","Quãng đường tới 10^5 · 10^9: dùng long."]}},{t:"Bao nhiêu cách đi nhanh nhất?",d:"Đồ thị vô hướng có trọng số như bài trước (2 ≤ n ≤ 10^5, 1 ≤ m ≤ 2·10^5, 1 ≤ w ≤ 10^9). Đầu ra: quãng đường ngắn nhất từ 1 tới n và số đường đi ngắn nhất khác nhau (lấy dư cho 10^9 + 7), cách nhau một dấu cách; hoặc -1 nếu không tới được. Hai đường khác nhau nếu dãy cạnh khác nhau (cạnh song song tính là khác).",tests:[{in:"4 5\n1 2 1\n1 3 1\n2 4 1\n3 4 1\n1 4 2",out:"2 3"},{in:"3 1\n1 2 5",out:"-1"},{in:"2 2\n1 2 3\n1 2 3",out:"3 2"},{in:"6 8\n1 2 7\n1 3 9\n1 6 14\n2 3 10\n2 4 15\n3 4 11\n3 6 2\n6 5 9",out:"11 1"},{in:"30 70\n30 5 3\n28 19 2\n20 1 2\n7 5 3\n27 23 3\n16 23 1\n7 16 1\n12 1 1\n20 13 2\n16 3 3\n13 19 2\n8 27 2\n16 20 3\n19 3 1\n4 16 1\n18 12 3\n22 4 2\n18 9 3\n12 9 1\n6 11 2\n5 25 3\n8 10 1\n22 10 3\n25 13 2\n13 25 3\n16 27 2\n20 18 1\n28 26 1\n5 11 2\n5 30 1\n3 8 2\n27 29 2\n7 2 1\n3 9 1\n11 1 3\n24 18 1\n12 6 2\n23 14 1\n18 4 2\n25 1 3\n21 20 3\n27 6 3\n9 3 3\n6 26 3\n11 23 2\n28 1 1\n18 6 1\n25 20 1\n2 21 1\n26 2 2\n26 5 1\n6 20 3\n14 8 2\n13 16 3\n20 21 3\n1 9 3\n21 10 2\n28 3 1\n7 6 2\n21 27 1\n2 29 2\n4 29 3\n1 6 1\n25 24 1\n14 18 3\n6 17 3\n26 29 1\n8 28 2\n25 24 2\n26 5 3",out:"4 1"},{in:"16 29\n1 2 1\n2 3 1\n3 4 1\n4 5 1\n5 6 1\n6 7 1\n7 8 1\n8 9 1\n9 10 1\n10 11 1\n11 12 1\n12 13 1\n13 14 1\n14 15 1\n15 16 1\n1 3 2\n2 4 2\n3 5 2\n4 6 2\n5 7 2\n6 8 2\n7 9 2\n8 10 2\n9 11 2\n10 12 2\n11 13 2\n12 14 2\n13 15 2\n14 16 2",out:"15 987"}],start:"#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<pair<int,int>>> adj(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v, w;\n        cin >> u >> v >> w;\n        adj[u].push_back({v, w});\n        adj[v].push_back({u, w});\n    }\n    const long long INF = 4e18, MOD = 1000000007;\n    vector<long long> dist(n + 1, INF), soDuong(n + 1, 0);\n    // Dijkstra; nới ngắn hơn hẳn thì chép số đường, bằng thì cộng thêm\n    cout << -1 << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const r=[];for(let i=1;i<n;i++)r.push(i+" "+(i+1)+" "+(1+(i*7)%10));for(let i=1;i+3<=n;i+=3)r.push(i+" "+(i+3)+" "+(5+(i*13)%40));return n+" "+r.length+"\n"+r.join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>140*n*Math.log2(n)+300,why:"Bản O(n²) tìm đỉnh gần nhất bằng cách duyệt quá chậm với đồ thị thưa."},py:{start:"import heapq\n\nn, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]       # adj[u]: các cặp (v, w)\nfor _ in range(m):\n    u, v, w = map(int, input().split())\n    adj[u].append((v, w))\n    adj[v].append((u, w))\nMOD = 10**9 + 7\nINF = float(\"inf\")\ndist = [INF] * (n + 1)\nso_duong = [0] * (n + 1)\n# Dijkstra; nới ngắn hơn hẳn thì chép số đường, bằng thì cộng thêm\nprint(-1)",hints:["Chạy Dijkstra kèm mảng so_duong, so_duong[1] = 1.","Nới cạnh u → v: đường mới ngắn hơn hẳn thì so_duong[v] = so_duong[u]; bằng đúng dist[v] thì so_duong[v] += so_duong[u].","Đúng vì mọi trọng số dương: khi u được chốt, so_duong[u] đã đủ."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        var adj = new List<int[]>[n + 1];      // adj[u]: các cặp { v, w }\n        for (int u = 0; u <= n; u++) adj[u] = new List<int[]>();\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(new[] { e[1], e[2] });\n            adj[e[1]].Add(new[] { e[0], e[2] });\n        }\n        const long INF = long.MaxValue, MOD = 1000000007;\n        long[] dist = new long[n + 1], soDuong = new long[n + 1];\n        Array.Fill(dist, INF);\n        // Dijkstra; nới ngắn hơn hẳn thì chép số đường, bằng thì cộng thêm\n        Console.WriteLine(-1);\n    }\n}",hints:["Chạy Dijkstra kèm mảng soDuong, soDuong[1] = 1.","Nới cạnh u → v: đường mới ngắn hơn hẳn thì soDuong[v] = soDuong[u]; bằng đúng dist[v] thì soDuong[v] += soDuong[u].","Đúng vì mọi trọng số dương: khi u được chốt, soDuong[u] đã đủ."]}},{t:"Băng qua địa hình",d:"Bản đồ R × C, đi vào ô (i, j) tốn a[i][j] sức (0 ≤ a ≤ 9). Xuất phát ở ô trên trái (tốn a[0][0]), mỗi bước sang ô chung cạnh (cả bốn hướng), cần tới ô dưới phải. Đầu vào: R C (1 ≤ R, C ≤ 500) rồi R dòng. Đầu ra: tổng sức nhỏ nhất.",tests:[{in:"3 3\n1 3 1\n1 5 1\n4 2 1",out:"7"},{in:"1 1\n5",out:"5"},{in:"3 5\n1 9 1 1 1\n1 9 1 9 1\n1 1 1 9 1",out:"11"},{in:"2 2\n0 0\n0 0",out:"0"},{in:"12 15\n4 4 7 7 0 3 5 6 0 2 2 2 0 8 8\n6 2 1 9 0 9 1 2 4 1 5 0 0 4 8\n4 8 0 5 9 3 0 1 3 0 5 6 9 0 1\n1 3 4 0 5 6 9 8 3 7 8 2 9 4 0\n2 0 1 4 6 4 3 7 7 5 7 4 3 4 8\n3 2 3 9 7 4 8 2 6 2 7 7 9 5 4\n9 6 4 8 6 1 9 3 5 0 4 2 7 9 9\n7 1 5 9 8 0 7 4 8 3 8 5 8 9 0\n9 2 7 8 2 0 1 2 6 8 1 6 5 2 4\n2 4 7 3 9 4 7 2 4 2 4 8 0 1 8\n3 7 7 4 1 4 1 6 5 0 4 8 3 5 6\n6 1 5 6 6 0 9 4 4 4 5 4 2 1 4",out:"65"}],start:"#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int R, C;\n    cin >> R >> C;\n    vector<vector<int>> a(R, vector<int>(C));\n    for (int i = 0; i < R; i++)\n        for (int j = 0; j < C; j++) cin >> a[i][j];\n    // Dijkstra trên lưới: mỗi ô là một đỉnh, đi vào ô (x, y) tốn a[x][y]\n    cout << 0 << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const C=Math.floor(n/5);const z=Array(C).fill(0),r1=Array(C).fill(9),r3=Array(C).fill(9);r1[C-1]=0;r3[0]=0;return "5 "+C+"\n"+[z,r1,z,r3,z].map(r=>r.join(" ")).join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>150*n*Math.log2(n)+300,why:"Lặp lại việc nới mọi ô tới khi không đổi tốn O((R·C)²) với đường đi ngoằn ngoèo."},py:{start:"import heapq\n\nR, C = map(int, input().split())\na = [list(map(int, input().split())) for _ in range(R)]\n# Dijkstra trên lưới: mỗi ô là một đỉnh, đi vào ô (x, y) tốn a[x][y]\nprint(0)",hints:["Đi được cả bốn hướng nên quy hoạch động theo hàng (bài 49) không đúng.","Coi mỗi ô là một đỉnh, cạnh vào ô (x, y) dài a[x][y] ≥ 0: chạy Dijkstra với heapq chứa (d, x, y).","Khởi đầu d[0][0] = a[0][0]; đáp án d[R − 1][C − 1]."]},cs:{start:"using System;\nusing System.Collections.Generic;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] rc = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int R = rc[0], C = rc[1];\n        int[][] a = new int[R][];\n        for (int i = 0; i < R; i++) a[i] = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        // Dijkstra trên lưới: mỗi ô (x, y) là đỉnh x * C + y, đi vào ô (x, y) tốn a[x][y]\n        Console.WriteLine(0);\n    }\n}",hints:["Đi được cả bốn hướng nên quy hoạch động theo hàng (bài 49) không đúng.","Coi mỗi ô là một đỉnh x · C + y, cạnh vào ô (x, y) dài a[x][y] ≥ 0: chạy Dijkstra với PriorityQueue<int, int>.","Khởi đầu d[0] = a[0][0]; đáp án d[R · C − 1]."]}}]);

